DO $fix$ DECLARE definition text; old_fragment text := 'jsonb_array_elements(payload->''items'') item JOIN storage.objects o ON o.bucket_id=item->>''bucket'' AND o.name=item->>''path'''; BEGIN definition:=pg_get_functiondef('private.media_cleanup(text,jsonb)'::regprocedure); IF position(old_fragment in definition)=0 THEN RAISE EXCEPTION 'Unexpected function definition'; END IF; EXECUTE replace(definition,old_fragment,'jsonb_array_elements(payload->''items'') AS entry(value) JOIN storage.objects o ON o.bucket_id=entry.value->>''bucket'' AND o.name=entry.value->>''path'''); END $fix$;
